function encodeSweepSrgb(value) { return value <= 0.0031308 ? 12.92 * value : 1.055 * value ** (1 / 2.4) - 0.055; }
function createCie1931BinCenterProjection(cieRows, spectralBasis) {
	const matrix = [[], [], []];
	for (const channel of spectralBasis.channels) {
		const lower = cieRows.get(Math.floor(channel.center.value)); const upper = cieRows.get(Math.ceil(channel.center.value)); requireCondition(lower && upper, `CIE 1931 does not bracket ${channel.center.value} nm.`); const fraction = channel.center.value - Math.floor(channel.center.value); const matching = lower.map((value, axis) => value + fraction * (upper[axis] - value));
		for (let axis = 0; axis < 3; axis += 1) matrix[axis].push(matching[axis] * channel.width.value * 683);
	}
	return matrix;
}
function sweepPlate(candidates, { title = 'Independent RGB endpoint sweep', subtitle = 'one atmosphere acquisition · standard spectral integration · no Sun-specific Color branch' } = {}) {
	const imageWidth = 321; const imageHeight = 181; const cellWidth = 341; const rowHeight = 235; const headerHeight = 76; const width = cellWidth * 4; const height = headerHeight + rowHeight * candidates.length;
	const rows = candidates.map((candidate, rowIndex) => { const y = headerHeight + rowIndex * rowHeight; const cells = candidate.images.map((item, columnIndex) => { const x = columnIndex * cellWidth + 10; return `<g><image x="${x}" y="${y + 34}" width="${imageWidth}" height="${imageHeight}" href="data:image/png;base64,${item.png.toString('base64')}"/><rect x="${x}" y="${y + 34}" width="${imageWidth}" height="${imageHeight}" fill="none" stroke="#303844"/><text x="${x + imageWidth / 2}" y="${y + 229}" text-anchor="middle" fill="#d8dee8" font-family="Segoe UI,sans-serif" font-size="13">${label(item.id)}</text></g>`; }).join(''); return `<text x="12" y="${y + 23}" fill="${candidate.accepted ? '#8fe3a1' : '#f0b07a'}" font-family="Segoe UI,sans-serif" font-size="15" font-weight="600">${candidate.id} · ${candidate.accepted ? 'passes gates' : `${candidate.failedGateCount} failed gates`}</text>${cells}`; }).join('');
	return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><rect width="100%" height="100%" fill="#080a0e"/><text x="${width / 2}" y="30" text-anchor="middle" fill="#f4f7fb" font-family="Segoe UI,sans-serif" font-size="24">${title}</text><text x="${width / 2}" y="55" text-anchor="middle" fill="#aeb8c5" font-family="Segoe UI,sans-serif" font-size="14">${subtitle}</text>${rows}</svg>`;
}

